(()=>{
const q=s=>document.querySelector(s), all=s=>[...document.querySelectorAll(s)], personal=()=>q('#applicant').value==='individual';
const input=(id,title,type='text',req=true)=>`<label class="field"><span>${title}${req?'':' <small>(optional)</small>'}</span><input id="${id}" type="${type}" ${req?'required':''} ${type==='number'?'min="0" step="0.01"':''}></label>`;
const sel=(id,title,opts,req=true)=>`<label class="field"><span>${title}${req?'':' <small>(optional)</small>'}</span><select id="${id}" ${req?'required':''}><option value="">Select…</option>${opts.map(o=>'<option>'+o+'</option>').join('')}</select></label>`;
const area=(id,title,req=true)=>`<label class="field"><span>${title}${req?'':' <small>(optional)</small>'}</span><textarea id="${id}" ${req?'required':''}></textarea></label>`;
const checks=(id,title,opts)=>`<fieldset id="${id}"><legend>${title}</legend><div class="checks">${opts.map(o=>'<label><input type="checkbox" value="'+o+'">'+o+'</label>').join('')}</div></fieldset>`;
const country=(id,title,multi=false)=>multi?`<div class="field"><span>${title}</span><input type="hidden" id="${id}"><div class="country-picker" id="${id}-picker"></div></div>`:sel(id,title,countryNames);
const currency=(id,title)=>checks(id,title,['EUR','GBP','USD','Other'])+`<div id="${id}-other" hidden>${input(id+'-text','Please specify other currencies')}</div>`;
function page(n,title,lead,body){const s=document.createElement('div');s.className='screen';s.hidden=true;s.dataset.screen=n;s.innerHTML='<div class="account-section">PRIVATE BANKING</div><h1>'+title+'</h1><p class="lead">'+lead+'</p>'+body;q('main').append(s);}
page(20,'Tell us about yourself','A few details to identify suitable private-banking options.',`<section class="panel">${sel('pb-assets','Your approximate liquid assets — EUR equivalent',['Below €100,000','€100,000 to under €1 million','€1 million to €10 million','Above €10 million'])}<p class="hint">Cash, deposits and readily marketable investments you own. Exclude property and private-company valuations.</p><p class="note" id="pb-eligibility" hidden></p>${input('pb-name','Full legal name')}<div class="grid">${country('pb-nationality','Nationality / nationalities',true)}${country('pb-residence','Country of residence')}</div>${country('pb-tax','Country / countries of tax residence',true)}</section>`);
page(21,'Your private-banking needs','Tell us what you would like the banking relationship to provide.',`<section class="panel">${checks('pb-needs','What are you looking for?',['Safekeeping and diversification','Savings / term deposits','Investment advice','Managed investment portfolio','Securities custody / trading','Lending against investments','Other'])}<div id="pb-needs-other" hidden>${input('pb-needs-text','Please describe your needs')}</div><div class="grid">${input('pb-transfer','Amount you expect to place with the bank — EUR equivalent','number')}${sel('pb-timeline','When would you like to start?',['Within 1 month','Within 1–3 months','Within 3–6 months','Flexible / exploring options'])}</div><p class="hint">This may be less than your total liquid assets. Provider minimums vary.</p>${currency('pb-currencies','Currencies you need')}${input('pb-bank-country','Preferred bank country, if any','text',false)}${input('pb-language','Preferred relationship-manager language','text',false)}</section>`);
page(22,'Your background & source of wealth','How did you build your overall wealth?',`<section class="panel">${sel('pb-occupation','Current professional status',['Business owner / entrepreneur','Employed professional / executive','Self-employed','Investor','Retired','Other'])}${input('pb-linkedin','LinkedIn profile URL','url',false)}${area('pb-career','Brief professional background — role, business or former occupation')}<p class="hint">A short summary is enough; no CV upload is needed.</p></section><section class="panel">${checks('pb-wealth','Main sources of wealth — select all that apply',['Employment / professional income','Business ownership / dividends','Sale of a business','Investments','Property income / sale','Inheritance','Gift / family wealth','Other'])}${area('pb-wealth-story','Briefly explain how and when your wealth was built')}<p class="hint">For example: the business or employer, years involved, or a significant sale or inheritance.</p></section>`);
page(23,'Source of funds & expected activity','Where will the money for this account come from?',`<section class="panel">${checks('pb-funds','Origin of the initial funds — select all that apply',['Accumulated earnings / savings','Business dividends / distributions','Investment sale / proceeds','Property sale','Business sale','Inheritance','Gift','Other'])}${area('pb-funds-story','Briefly explain the origin of the funds you intend to transfer')}<p class="hint">Name the underlying earnings, sale or event, rather than only the bank holding the money.</p><div class="grid">${input('pb-origin-bank','Sending bank / institution, if known','text',false)}${country('pb-origin-country','Country / countries the funds will be sent from',true)}</div>${sel('pb-own-funds','Will the funds come from an account in your own name?',['Yes','No','Not yet determined'])}<div id="pb-third-party" hidden>${area('pb-third-party-detail','Who will send the funds, and what is their relationship to you?')}</div>${sel('pb-evidence','Could you provide evidence of the wealth and funds if requested?',['Yes','Some evidence is available','I would like guidance on what is needed'])}</section><section class="panel">${sel('pb-activity','Expected ongoing account activity',['Mainly hold / invest assets, occasional transfers','Regular investment activity','Regular incoming and outgoing transfers','Not yet determined'])}<div id="pb-regular" hidden><div class="grid">${country('pb-incoming','Expected incoming countries',true)}${country('pb-outgoing','Expected outgoing countries',true)}</div>${area('pb-transfer-use','Main reasons for the regular transfers')}</div></section>`);
page(24,'Contact & review','Review your request before exploring potential providers.',`<section class="panel">${input('pb-email','Email address','email')}${input('pb-phone','Phone number','tel',false)}${sel('pb-current-bank','Do you have an existing private-banking relationship?',['Yes','No','Prefer not to answer'],false)}<div id="pb-current-bank-details" hidden>${input('pb-current-bank-name','Bank name and country','text',false)}</div></section><section class="panel"><h2>Your request</h2><dl class="summary" id="pb-summary"></dl><label class="checkline"><input id="pb-accuracy" type="checkbox"><span>I confirm these details are accurate to the best of my knowledge.</span></label><p class="hint">SOPHIMA reviews introduction requests. You approve the institution and information to be shared.</p><button type="button" id="pb-meeting">Discuss my needs first</button></section>`);
['pb-nationality','pb-tax','pb-origin-country','pb-incoming','pb-outgoing'].forEach(id=>initCountryPicker(q('#'+id+'-picker'),id.replaceAll('-',' ')+' search',q('#'+id)));
function condition(id,target,predicate){q('#'+id).addEventListener('change',()=>q('#'+target).hidden=!predicate(q('#'+id).value));}
condition('pb-own-funds','pb-third-party',v=>v==='No');condition('pb-activity','pb-regular',v=>v==='Regular incoming and outgoing transfers');condition('pb-current-bank','pb-current-bank-details',v=>v==='Yes');
['pb-needs','pb-currencies'].forEach(id=>q('#'+id).addEventListener('change',()=>q('#'+id+'-other').hidden=!q('#'+id+' input[value="Other"]').checked));
const discuss=document.createElement('button');discuss.type='button';discuss.textContent='Discuss my eligibility';discuss.className='mini';discuss.onclick=()=>q('#meeting').showModal();q('#pb-eligibility').after(discuss);
q('#pb-assets').onchange=()=>{const v=q('#pb-assets').value,notice=q('#pb-eligibility');notice.hidden=!['Below €100,000','Above €10 million'].includes(v);notice.textContent=v==='Below €100,000'?'This private-banking service currently starts at €100,000 in liquid assets.':'Your profile is above the current intake bands. Please discuss your requirements with SOPHIMA.';};
q('#pb-meeting').onclick=()=>q('#meeting').showModal();
const oldFlow=activeFlow;activeFlow=function(){return personal()?[0,1,20,21,22,23,24]:oldFlow();};
Object.assign(labels,{20:'Personal profile',21:'Banking needs',22:'Background & wealth',23:'Funds & activity',24:'Contact & review'});
const oldRefresh=refreshFlow;refreshFlow=function(){oldRefresh();if(personal()){q('.steps [data-page="1"]').textContent='1 · Applicant';const a=q('[data-screen="24"] .actions');a.innerHTML='<button type="button" id="pb-back">Back</button><button type="button" class="primary" id="pb-submit">Find matching institutions</button>';q('#pb-back').onclick=()=>showPage(23);q('#pb-submit').onclick=()=>{if(!validPersonal(24))return;showPage(6);note('Preview only: no matching request has been sent. Bank acceptance and minimums require provider review.');};}};window.refreshFlow=refreshFlow;
function validPersonal(n){const s=q('[data-screen="'+n+'"]');const invalid=[...s.querySelectorAll('input,select,textarea')].find(e=>{let a=e.parentElement;while(a&&a!==s){if(a.hidden)return false;a=a.parentElement;}return e.type!=='hidden'&&!e.checkValidity();});if(invalid){note('Please complete '+(invalid.closest('label')?.querySelector('span')?.textContent||'the highlighted field')+'.');invalid.focus();return false;}
if(n===21&&!q('#pb-assets').value){note('Please select your current liquid-asset band.');return false;}if(n===20){if(!q('#pb-nationality').value||!q('#pb-tax').value){note('Please select nationality and tax-residence countries.');return false;}}
const groups={21:['pb-needs','pb-currencies'],22:['pb-wealth'],23:['pb-funds']};for(const id of groups[n]||[]){if(!q('#'+id+' input:checked')){note('Please select at least one option for '+q('#'+id+' legend').textContent+'.');return false;}}
if(n===23&&(!q('#pb-origin-country').value||(q('#pb-activity').value==='Regular incoming and outgoing transfers'&&(!q('#pb-incoming').value||!q('#pb-outgoing').value)))){note('Please select the relevant sending and transaction countries.');return false;}if(n===24&&!q('#pb-accuracy').checked){note('Please confirm the accuracy of your details.');return false;}return true;}
function summary(){const target=q('#pb-summary');target.replaceChildren();for(const [label,value] of [['Name',q('#pb-name').value],['Liquid assets',q('#pb-assets').value],['Nationality',q('#pb-nationality').value],['Residence',q('#pb-residence').value],['Expected placement (EUR)',q('#pb-transfer').value],['Source of wealth',q('#pb-wealth-story').value],['Source of funds',q('#pb-funds-story').value]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value||'Not yet provided';target.append(dt,dd);}}
const oldShow=showPage;showPage=function(n){if(!personal()){oldShow(n);return;}const flow=activeFlow();if(!flow.includes(n)&&n!==6)return;if(n===6){for(const p of [20,21,22,23,24]){if(!validPersonal(p)){currentPage=p;all('.screen').forEach(s=>s.hidden=Number(s.dataset.screen)!==p);refreshFlow();return;}}}else if(flow.indexOf(n)>flow.indexOf(currentPage)&&currentPage>=20&&!validPersonal(currentPage))return;currentPage=n;all('.screen').forEach(s=>s.hidden=Number(s.dataset.screen)!==n);q('.steps').hidden=n===0;q('#feedback').textContent='';refreshFlow();if(n===24)summary();scrollTo(0,0);};
function applicantUI(){const is=personal(),company=q('[data-screen="1"]');company.querySelector('h1').textContent=is?'Who are you applying for?':'Tell us about your company';company.querySelectorAll('.panel')[1].hidden=is;q('#account-type').closest('label').hidden=is;company.querySelector('.eyebrow').textContent=is?'PRIVATE BANKING':'STEP 1 · COMPANY PROFILE';if(!activeFlow().includes(currentPage))currentPage=1;refreshFlow();}
q('#applicant').onchange=()=>{applicantUI();showPage(1);};
window.applyApplicantUI=applicantUI;applicantUI();
})();
